examples.template:
MonarchPendingInvitesList(
    invites,
    onResend: { _ in
        // The app sends the invitation again on the server.
    },
    onRevoke: { id in
        invites.removeAll { $0.id == id }
    }
)

examples.setupTemplate:
@State private var invites = [
    MonarchPendingInvite(
        id: {{invites.0.id}},
        email: {{invites.0.email}},
        role: {{invites.0.role}},
        invitedBy: {{invites.0.invitedBy}},
        sentAt: Date(timeIntervalSinceNow: {{invites.0.sentDays|double}} * 86_400),
        expiresAt: Date(timeIntervalSinceNow: {{invites.0.expiresDays|double}} * 86_400),
        link: "https://example.com/join/" + {{invites.0.id}}
    ),
    MonarchPendingInvite(
        id: {{invites.1.id}},
        email: {{invites.1.email}},
        role: {{invites.1.role}},
        invitedBy: {{invites.1.invitedBy}},
        sentAt: Date(timeIntervalSinceNow: {{invites.1.sentDays|double}} * 86_400),
        expiresAt: Date(timeIntervalSinceNow: {{invites.1.expiresDays|double}} * 86_400),
        link: "https://example.com/join/" + {{invites.1.id}}
    ),
]

